  const href=URL.createObjectURL(blob),a=document.createElement("a");a.href=href;a.download=name;document.body.append(a);a.click();a.remove();
  setTimeout(()=>URL.revokeObjectURL(href),10000);return {name,bytes:blob.size};
}
